#!/bin/sh
# 🚦️ Runs a bun script through the capacity queue under /usr/bin/time -l: queued.sh <label> <memory MB> <timeout s> <script and args…>
# The log (queue lines, script output, resident peak and times) goes to <generated>/<label>.log; BUN_FLAGS adds flags before the script (for example --cpu-prof).
# Do not edit this file while a run of it is in flight: sh reads a script as it goes.
set -u
R=/Users/ueli/Documents/semio
G="$R/.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️11/☀️22/GET-STAFFAGE-RUNNING-END-TO-END-AND-FINISH-ALL-STAFFAGE-TICKETS/🗑️generated/matrix/MM"
BUN=$(ls ~/Library/Caches/semio/runtimes/bun/*/bun | head -1)
label=$1; memory=$2; limit=$3; shift 3
mkdir -p "$G"
cd "$R" || exit 1
queued=$(date +%s)
repo capacity run --memory="$memory" -- /usr/bin/time -l timeout "$limit" "$BUN" ${BUN_FLAGS:-} "$@" > "$G/$label.log" 2>&1
code=$?
echo "exit $code, queued+run $(( $(date +%s) - queued )) s" >> "$G/$label.log"
grep -E "maximum resident| real |^exit" "$G/$label.log"
